// Presentation preferences are separate from round rules and score storage.
const KEY='overtime-pinball-labels-v1';
export class LabelPreference{
 constructor(storage){this.storage=storage;this.enabled=false;this.saved=true;try{this.enabled=JSON.parse(storage?.getItem(KEY)||'null')?.enabled===true;}catch{}}
 set(enabled){this.enabled=enabled===true;try{if(!this.storage)throw Error('storage unavailable');this.storage.setItem(KEY,JSON.stringify({enabled:this.enabled}));this.saved=true;}catch{this.saved=false;}}
}
export function poolNotice(state,event,now){
 const phase=event?.phase||'collecting';
 if(state.key!==phase||now<(state.last??now)){state.key=phase;state.until=now+3;}
 state.last=now;
 // A pending claim is actionable and must never disappear with its deadline.
 return phase==='claim'||phase==='ready'||phase==='frenzy'&&now<state.until;
}
// Read existing authoritative presentation nodes, never introduce another input path.
export function mobileFocus(doc){
 const visible=id=>{const el=doc.getElementById(id);return el&&!el.hidden?el:null;};
 const text=id=>doc.getElementById(id)?.textContent||'';
 const progress=el=>{const p=el?.querySelector('progress');return p&&!p.hidden&&p.max>0?Math.max(0,Math.min(1,p.value/p.max)):null;};
 const work=visible('activityPanel');
 if(work){const match=doc.getElementById('activityBar')?.style.transform.match(/scaleX\(([\d.]+)\)/);return{kind:'work',title:text('activityTitle'),text:text('activityText'),ratio:match?Math.max(0,Math.min(1,Number(match[1]))):null};}
 const route=visible('routeChoice');if(route)return{kind:'route',title:route.querySelector('b')?.textContent||'',text:[route.querySelector('span')?.textContent,route.querySelector('small')?.textContent].filter(Boolean).join(' · '),ratio:progress(route)};
 const offer=visible('interactionOffer');if(offer)return{kind:'offer',title:offer.querySelector('b')?.textContent||'',text:offer.querySelector('small')?.textContent||'',ratio:progress(offer)};
 for(const [id,kind]of[['doorWarning','rescue'],['routeReward','route-reward'],['comboRoute','combo'],['centralPrompt','central'],['bossStatus','boss'],['lotteryStatus','lottery']]){const el=visible(id);if(el?.textContent.trim())return{kind,title:'',text:el.textContent,ratio:null};}
 const pool=visible('overtimeStatus');if(doc.body.dataset.poolNotice==='true'&&pool?.textContent)return{kind:'pool',title:'',text:pool.textContent,ratio:null};
 const comic=visible('comic');if(comic?.classList.contains('pop')&&comic.textContent)return{kind:'reward',title:'',text:comic.textContent,ratio:null};
 const mail=visible('mailStatus');if(mail?.textContent)return{kind:'mail',title:'',text:mail.textContent,ratio:null};
 return null;
}
export function mountMobileUI({document,storage,labels}){
 const preference=new LabelPreference(storage),notice={key:null,until:0};
 const cue=document.createElement('div');cue.id='mobileCue';cue.hidden=true;cue.setAttribute('aria-live','polite');const cueTitle=document.createElement('b'),cueText=document.createElement('span'),cueBar=document.createElement('progress');cueBar.max=1;cueBar.setAttribute('aria-label','目前操作進度或剩餘時間');cue.append(cueTitle,cueText,cueBar);document.body.append(cue);
 const details=document.createElement('p');details.id='poolDetails';document.querySelector('#pauseScreen .pause-settings')?.after(details);
 const choices=[...document.querySelectorAll('.label-names-option')];
 const syncPreference=()=>{labels.setNamesVisible(preference.enabled);for(const el of choices)el.checked=preference.enabled;for(const el of document.querySelectorAll('.label-save-notice')){el.hidden=preference.saved;el.textContent=preference.saved?'':'此裝置無法儲存，設備名稱設定只適用本次遊玩。';}};
 for(const el of choices)el.addEventListener('change',()=>{preference.set(el.checked);syncPreference();});syncPreference();
 return{sync(game){
 document.body.dataset.poolNotice=String(poolNotice(notice,game.overtime,game.playClock||0));
 details.textContent=document.getElementById('overtimeStatus')?.textContent||'';
 const focus=game.round?.ending||game.round?.reentry?null:mobileFocus(document);
 cue.hidden=!focus;cue.dataset.kind=focus?.kind||'';
 const shortLandscape=document.defaultView?.matchMedia?.('(orientation:landscape) and (max-height:600px)').matches&&!document.body.classList.contains('desktop-layout');
 const concise=shortLandscape&&focus?.kind==='route'?{...focus,title:'',text:focus.text.replace(' · ','\n')}:shortLandscape&&focus?.kind==='offer'?{...focus,title:'',text:'按 L / R 進入互動；不按繼續彈跳'}:focus;
 cueTitle.textContent=concise?.title||'';cueTitle.hidden=!concise?.title;
 cueText.textContent=concise?.text||'';cueBar.hidden=focus?.ratio==null;if(focus?.ratio!=null)cueBar.value=focus.ratio;

 }};
}

import {withProvenanceSession,manifestText} from './provenance-session.mjs';
// Exact additive boundary for the approved PinballNavOrder import. Live behavior tests
// continue reading node:fs and runtime modules, never this historical view.
import {readFileSync as actual,readdirSync as actualDirectory} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {resolve,relative,sep,isAbsolute} from 'node:path';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../../',import.meta.url));
export const sha256=b=>createHash('sha256').update(b).digest('hex');
export const gitBlob=b=>createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');
const baselineBytes=actual(new URL('../../docs/pinball-nav-order/BASELINE.json',import.meta.url));
assert.equal(sha256(baselineBytes),'6cc1b45d10c531e7e21ab7e3d9e21c7b381ae857b01de2f9571114108b510201','immutable PinballNavOrder parent and admitted paths');
const freeze=value=>{if(value&&typeof value==='object'){Object.values(value).forEach(freeze);Object.freeze(value);}return value;};
export const baseline=freeze(JSON.parse(baselineBytes));
const previous=new Map(baseline.files.map(f=>[f.path,f.gitBlob]));
export function verifyBase(b){
 assert.equal(b.baseCommit,'0b3b401bd666c2209fe55e00ec4c3eb5a598e351');assert.equal(b.baseTree,'14650661f303373d5b23bfd89b2d6b809c6bbd94');assert.deepEqual(b,baseline);
 const tree={};for(const f of b.files){const parts=f.path.split('/');let d=tree;for(const name of parts.slice(0,-1))d=d[name]??={};assert.ok(!d[parts.at(-1)],'duplicate parent path');d[parts.at(-1)]={file:f};}
 function digest(d){const entries=Object.entries(d).sort(([a,x],[b,y])=>Buffer.compare(Buffer.from(a+(x.file?'':'/')),Buffer.from(b+(y.file?'':'/'))));const bytes=Buffer.concat(entries.map(([n,x])=>Buffer.concat([Buffer.from(`${x.file?x.file.mode:'40000'} ${n}\0`),Buffer.from(x.file?x.file.gitBlob:digest(x),'hex')])));return createHash('sha1').update(`tree ${bytes.length}\0`).update(bytes).digest('hex');}
 assert.equal(digest(tree),b.baseTree);return true;
}
verifyBase(baseline);
const manifestPath='docs/pinball-nav-order/MANIFEST.json';
let cachedText,cached;const validated=new WeakSet();
function uncached_manifest(){const url=new URL('../../'+manifestPath,import.meta.url),text=manifestText(url,()=>actual(url,'utf8'));if(text!==cachedText){const parsed=freeze(JSON.parse(text));cachedText=text;cached=parsed;}return cached;}

export function validate(m){
 if(m===cached&&validated.has(m))return m;
 assert.equal(m.baseCommit,baseline.baseCommit);assert.equal(m.baseTree,baseline.baseTree);
 assert.deepEqual(m.files.map(f=>f.path).sort(),baseline.modifiedPaths);
 assert.deepEqual([...m.addedPaths].sort(),baseline.addedPaths);
 assert.deepEqual(m.addedFiles.map(f=>f.path).sort(),baseline.addedPaths.filter(p=>p!==manifestPath));
 for(const f of m.files){const b=Buffer.from(f.beforeText);assert.equal(f.beforeGitBlob,previous.get(f.path));assert.equal(gitBlob(b),f.beforeGitBlob);assert.equal(sha256(b),f.beforeSha256);assert.match(f.gitBlob,/^[a-f0-9]{40}$/);assert.match(f.sha256,/^[a-f0-9]{64}$/);}
 for(const f of m.addedFiles){assert.match(f.gitBlob,/^[a-f0-9]{40}$/);assert.match(f.sha256,/^[a-f0-9]{64}$/);}
 if(m===cached)validated.add(m);return m;
}
function uncached_pinballNavOrderParentBytes(path,bytes,m=manifest()){
 validate(m);bytes=Buffer.from(bytes);const f=m.files.find(f=>f.path===path);if(!f)return bytes;
 const before=Buffer.from(f.beforeText);if(before.equals(bytes))return before;
 assert.equal(gitBlob(bytes),f.gitBlob,path+' pinballNavOrder live drift');assert.equal(sha256(bytes),f.sha256,path+' pinballNavOrder live SHA256 drift');return before;
}
function uncached_readBeforePinballNavOrder(file,options){
 const absolute=file instanceof URL?fileURLToPath(file):resolve(String(file)),path=relative(root,absolute).split(sep).join('/');
 if(!path||path==='..'||path.startsWith('../')||isAbsolute(path))return actual(file,options);
 const encoding=typeof options==='string'?options:options?.encoding;
 const bytes=actual(file,typeof options==='object'&&options?{...options,encoding:null}:undefined);
 const before=baseline.modifiedPaths.includes(path)?pinballNavOrderParentBytes(path,bytes):bytes;return encoding?before.toString(encoding):before;
}
function uncached_inventoryBeforePinballNavOrder(paths,{read=p=>actual(new URL('../../'+p,import.meta.url)),runtimeOnly=false}={}){
 assert.equal(new Set(paths).size,paths.length,'duplicate pinballNavOrder inventory');const m=validate(manifest());
 if(!paths.some(p=>m.addedPaths.includes(p)))return paths;
 const runtime=p=>/^(public|worker|src|config)\//.test(p),onlyRuntime=runtimeOnly||paths.every(runtime);
 const additions=m.addedPaths.filter(p=>!onlyRuntime||runtime(p));
 for(const p of additions)assert.equal(paths.filter(x=>x===p).length,1,p+' pinballNavOrder addition must appear once');
 for(const f of [...m.files,...m.addedFiles].filter(f=>!onlyRuntime||runtime(f.path))){const bytes=read(f.path);assert.equal(gitBlob(bytes),f.gitBlob,f.path+' pinballNavOrder inventory live drift');assert.equal(sha256(bytes),f.sha256,f.path+' pinballNavOrder inventory SHA256 drift');}
 return paths.filter(p=>!additions.includes(p));
